#' Plot a strange attractor.
#'
#' @inheritParams recolour
#' @inheritParams discretize
#' @param x Attractor, generated by [attractor_sprott_7e()]
#' @param trim_quantiles Numeric value, indicating a trim value. Quantiles below this value, as well as higher than `(1 - trim_quantiles)`
#' will be removed from data prior to plotting.
#' @param trans Transforming function
#' @param ... Other options passed to [plot()]
#'
#' @return Raster, invisibly
#' @family attractor
#' @export
#'
#' @importFrom graphics plot
#' @importFrom withr with_par
#'
#' @example inst/examples/example_plot.R
#'
plot.attractor <- function(
  x,
  palette = "BuPu",
  invert = FALSE,
  dims = c(600, 600),
  zero_colour = NA,
  trim_quantiles = 0,
  trans = "log1p",
  ...
) {
  assert_that(is.matrix(x))
  assert_that(length(dim(x)) == 2)
  z <- match.fun(trans)(x)
  class(z) <- "matrix"
  z <- recolour(
    z,
    palette = palette,
    invert = invert,
    zero_colour = zero_colour,
    trans = trans
  )
  withr::with_par(
    # set margins to zero, so that the plot fills the entire device
    list(mar = rep(0, 4), mai = rep(0, 4)),
    plot(z, ...)
  )
  invisible(z)
}
